window.docContents[159].resolve({"/Elementary-Functions/___4___24-Inverse-Trigonometric-Functions___-Further-Properties/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___24-Inverse-Trigonometric-Functions___-Further-Properties--___4___24-Inverse-Trigonometric-Functions___-Further-Properties":{"contents":"This section records three complementary parts of the inverse-trigonometric\ncalculus.  The first subsection gives convergent power-series and transformed\nseries, with their exact disks or half-plane conditions.  The second gives\nderivatives of the principal complex branches, including the real-part sign\nchoice for arcsecant and arccosecant.  The final subsection uses explicit value\nrelations: DLMF's capitalized inverse functions are multivalued, and every\nsquare root in those addition formulas may take either value.\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.24 Inverse Trigonometric Functions: Further Properties","header":"§4.24 Inverse Trigonometric Functions: Further Properties","id":"/Elementary-Functions/___4___24-Inverse-Trigonometric-Functions___-Further-Properties/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___24-Inverse-Trigonometric-Functions___-Further-Properties--___4___24-Inverse-Trigonometric-Functions___-Further-Properties"}});